{"tool":"write","path":"reports/export.py","content":""""Reports CSV exporter. Implement export_csv to satisfy TASK.txt."""


def _escape(value):
    """Escape a single field per RFC 4180 minimal quoting with quote doubling."""
    text = "" if value is None else str(value)
    if any(ch in text for ch in (",", '"', "\r", "\n")):
        return '"' + text.replace('"', '""') + '"'
    return text


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header."""
    seen = set()
    cols = []
    for col in columns:
        if not isinstance(col, str):
            raise ValueError("column names must be strings")
        if col in seen:
            raise ValueError("duplicate column name: %r" % col)
        seen.add(col)
        cols.append(col)

    parts = [",".join(_escape(c) for c in cols)]
    for row in rows:
        parts.append(",".join(_escape(row.get(col)) for col in cols))
    return "".join(part + "\r\n" for part in parts)
